'use client';

import {seasonFixturePlayMode} from '@/lib/season-play-mode';
import {createContext,useCallback,useContext,useEffect,useRef,useState,type FormEvent,type ReactNode} from 'react';
import type {Profile} from '@/lib/types';
import RankingEventPanel from '@/components/ranking-event-panel';
import SeasonComponentRules from '@/components/season-component-rules';
import {StartProcedureFields,readWinByTwo} from '@/components/bull-start-panel';
import OrganizerDrafts from '@/components/organizer-drafts';
import type {SeasonView,SeasonFixture} from '@/lib/seasons-types';
import './season-workspace.css';

type ObjectValue=Record<string,unknown>;
type ClubChoice={id:string;name:string;canManage?:boolean};
type PlayerChoice={id:string;name:string;clubId?:string;clubIds?:string[]};
type BoardChoice={id:string;name:string;clubId?:string};
type SeasonIndex={actorId?:string;seasons:SeasonView[];clubs:ClubChoice[];canCreateNational:boolean;canCreateInternal?:boolean;players?:PlayerChoice[];boards?:BoardChoice[]};
type CommandResult={ok:true;id:string;season:SeasonView;matchId?:string};
type Command=(action:ObjectValue&{type:string},message?:string)=>Promise<CommandResult|null>;
type Tab='overview'|'stand'|'program'|'results'|'stats'|'rules'|'manage';
const base='/app/competities';
const navigate=(path:string)=>window.location.assign(new URL(path,window.location.origin).href);
const FeedbackContext=createContext({error:'',message:''});
const states:Record<string,string>={draft:'Concept',registration:'Inschrijving open',planned:'Gepland',active:'Actief',completed:'Afgerond',archived:'Archief',scheduled:'Gepland',live:'Bezig',provisional:'Te bevestigen',confirmed:'Bevestigd',disputed:'Betwist',interrupted:'Onderbroken',administrative:'Administratief beslist',canceled:'Geannuleerd',waiting:'Wachtlijst',waitlisted:'Wachtlijst',invited:'Uitgenodigd',withdrawn:'Teruggetrokken',accepted:'Toegelaten',pending:'In behandeling'};
const formats:Record<string,string>={singles:'Singles',teams:'Teams',doubles:'Koppels',cup:'Beker',ladder:'Ladder','drop-in':'Vrije instuif',champions:'Champions Cup'};
const art:Record<string,string>={trophy:'M8 3h8v7a4 4 0 0 1-8 0V3ZM8 5H4v2a4 4 0 0 0 4 4m8-6h4v2a4 4 0 0 1-4 4m-4 3v6m-5 1h10',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm8-8a4 4 0 0 1 0 8',calendar:'M8 2v4m8-4v4M3 10h18M3 5h18v16H3Z',target:'M21 12a9 9 0 1 1-9-9m6 0-6 9m0-5a5 5 0 1 0 5 5m0-9h5v5',arrow:'M4 12h15m-6-6 6 6-6 6',back:'M20 12H5m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',table:'M3 5h18v14H3Zm0 5h18M8 10v9m7-9v9',download:'M12 3v12m-4-4 4 4 4-4M4 15v5h16v-5',shield:'m12 2 8 4v6c0 5-8 10-8 10s-8-5-8-10V6Zm-3 10 2 2 4-4',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM2 12h20M12 2c5 6 5 14 0 20-5-6-5-14 0-20Z'};
const obj=(value:unknown):ObjectValue=>value&&typeof value==='object'&&!Array.isArray(value)?value as ObjectValue:{};
const rows=(value:unknown):ObjectValue[]=>Array.isArray(value)?value.map(obj):[];
const txt=(value:unknown,fallback='')=>value==null?fallback:String(value);
const num=(value:unknown,fallback=0)=>Number.isFinite(Number(value))?Number(value):fallback;
const ids=(value:unknown):string[]=>Array.isArray(value)?value.filter((item):item is string=>typeof item==='string'):[];
const decimal=(value:unknown)=>typeof value==='number'&&Number.isFinite(value)?value.toLocaleString('nl-NL',{maximumFractionDigits:2}):'—';
const dateLabel=(value:unknown)=>typeof value==='string'&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString('nl-NL',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'}):'Nog te plannen';
const localDate=(value:unknown)=>typeof value==='string'&&Number.isFinite(Date.parse(value))?new Date(Date.parse(value)-new Date(value).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
const finalStates=new Set(['confirmed','administrative','canceled']);
function Glyph({name,size=17}:{name:string;size?:number}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={art[name]??art.target}/></svg>;}
function Badge({status,label}:{status:unknown;label?:string}){return <span className="season-badge" data-status={txt(status)}>{label??states[txt(status)]??txt(status,'—')}</span>;}
function Button({children,onClick,primary=false,icon,disabled=false,type='button'}:{children:ReactNode;onClick?:()=>void;primary?:boolean;icon?:string;disabled?:boolean;type?:'button'|'submit'}){return <button type={type} className={`season-button ${primary?'season-primary':'season-quiet'}`} onClick={onClick} disabled={disabled}>{icon&&<Glyph name={icon}/>}<span>{children}</span></button>;}
function LinkButton({children,href,primary=false,icon}:{children:ReactNode;href:string;primary?:boolean;icon?:string}){return <a className={`season-button ${primary?'season-primary':'season-quiet'}`} href={href}>{icon&&<Glyph name={icon}/>}<span>{children}</span></a>;}
function Panel({title,children,aside,className=''}:{title:string;children:ReactNode;aside?:ReactNode;className?:string}){return <section className={`season-panel ${className}`}><div className="season-section-head"><h2>{title}</h2>{aside}</div>{children}</section>;}
function Empty({title,children}:{title:string;children?:ReactNode}){return <div className="season-empty"><Glyph name="target" size={25}/><strong>{title}</strong>{children&&<p>{children}</p>}</div>;}
function Field({label,children,wide=false}:{label:string;children:ReactNode;wide?:boolean}){return <label className={`season-field${wide?' season-wide':''}`}><span>{label}</span>{children}</label>;}
function Select({name,options,value,required=false,disabled=false,onChange}:{name:string;options:[string,string][];value?:string;required?:boolean;disabled?:boolean;onChange?:(v:string)=>void}){return <select name={name} defaultValue={onChange?undefined:value} value={onChange?value:undefined} required={required} disabled={disabled} onChange={onChange?e=>onChange(e.target.value):undefined}>{options.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select>;}
function Check({name,children,checked=false,value}:{name:string;children:ReactNode;checked?:boolean;value?:string}){return <label className="season-check"><input type="checkbox" name={name} value={value} defaultChecked={checked}/><span>{children}</span></label>;}
function Definitions({values,className=''}:{values:[string,ReactNode][];className?:string}){return <dl className={`season-definition ${className}`}>{values.map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl>;}
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){const feedback=useContext(FeedbackContext),ref=useRef<HTMLDialogElement>(null);useEffect(()=>{const previous=document.activeElement instanceof HTMLElement?document.activeElement:null;const dialog=ref.current;dialog?.showModal();return()=>{dialog?.close();previous?.focus();};},[]);return <dialog ref={ref} className="season-dialog" aria-labelledby="season-dialog-title" onCancel={e=>{e.preventDefault();onClose();}}><div className="season-dialog-head"><h2 id="season-dialog-title">{title}</h2><button type="button" className="season-icon-button" aria-label="Sluiten" onClick={onClose}><Glyph name="close" size={20}/></button></div>{feedback.error&&<div className="season-feedback" data-error="true" role="alert">{feedback.error}</div>}{feedback.message&&<div className="season-feedback" role="status">{feedback.message}</div>}<div className="season-dialog-body">{children}</div></dialog>;}
function seasonEntries(season:SeasonView){return season.format==='teams'||season.format==='doubles'?rows(season.teams):rows(season.participants);}
function entryName(season:SeasonView,id:unknown){return txt(seasonEntries(season).find(entry=>entry.id===id||entry.playerId===id)?.name,'Nog te bepalen');}
function choices(season:SeasonView,index:SeasonIndex){return (season.eligiblePlayers??index.players??[]).map(player=>({id:txt(player.id),name:txt(player.name),clubIds:ids(player.clubIds)}));}
function boardsFor(season:SeasonView,index:SeasonIndex){return (season.boards??index.boards??[]).map(board=>({id:txt(board.id),name:txt(board.name),clubId:txt(board.clubId)}));}
function sideOf(season:SeasonView,fixture:ObjectValue,user:Profile){for(const side of ['home','away']){const id=fixture[`${side}Id`];if(id===user.id)return side;const team=rows(season.teams).find(team=>team.id===id);if(team&&(team.captainId===user.id||team.deputyId===user.id||ids(season.myTeamIds).includes(txt(team.id))))return side;}return '';}
function formValues(form:HTMLFormElement):ObjectValue{const data=new FormData(form),out:ObjectValue={...Object.fromEntries(data),...readWinByTwo(data)};const startPair=(home:string,away:string)=>{if(!data.get(home)&&!data.get(away))return undefined;if(!data.get(home)||!data.get(away))throw new Error('Vul voor een handicap beide startscorevelden in.');return [Number(data.get(home)),Number(data.get(away))];};out.sideStartScores=startPair('homeStart','awayStart')??null;for(const key of ['legMaximum','setMaximum'])if(data.has(key)&&!data.get(key))out[key==='legMaximum'?'legWinByTwo':'setWinByTwo']=null;const slotRules:ObjectValue={};for(let index=0;index<7;index++){const rule:ObjectValue={};for(const [suffix,key]of [['In','inRule'],['Out','outRule'],['Legs','bestOfLegs'],['Sets','bestOfSets']]){const raw=data.get(`slot${index}${suffix}`);if(raw)rule[key]=['Legs','Sets'].includes(suffix)?Number(raw):raw;}const pair=startPair(`slot${index}Home`,`slot${index}Away`);if(pair)rule.sideStartScores=pair;for(const[suffix,key]of[['LegMaximum','legWinByTwo'],['SetMaximum','setWinByTwo']])if(data.get(`slot${index}${suffix}`))rule[key]={maximum:Number(data.get(`slot${index}${suffix}`))};if(Object.keys(rule).length)slotRules[String(index)]=rule;}if(form.querySelector('[name=homeStart]'))out.slotRules=slotRules;for(const key of Object.keys(out))if(/^slot[0-6](In|Out|Home|Away|Legs|Sets|LegMaximum|SetMaximum)$/.test(key)||['homeStart','awayStart','legMaximum','setMaximum'].includes(key))delete out[key];for(const key of ['roundGating','allowMultipleTeams','returnLegs','cameraRequired'])out[key]=data.has(key);for(const key of ['bestOfSets','startScore','legs','roundDays','windowDays','boardCount','capacity','pointsWin','pointsDraw','pointsLoss','lineupHours','confirmHours','checkInMinutes','promotionPlaces','relegationPlaces','slotMinutes','inhaalWeeks','slotCount'])if(data.has(key))out[key]=Number(data.get(key));for(const key of ['divisions','blackouts'])if(data.has(key))out[key]=String(data.get(key)).split(',').map(v=>v.trim()).filter(Boolean);if(data.has('divisionLevels')){const names=out.divisions as string[];const levels=String(data.get('divisionLevels')).split(',').map(v=>Number(v.trim()));out.divisions=names.map((name,i)=>({name,level:levels[i]||i+1,targetSize:Number(data.get('divisionSize')??10),promotionPlaces:Number(data.get('promotionPlaces')??1),relegationPlaces:Number(data.get('relegationPlaces')??1)}));}return out;}

function SettingsFields({settings={},initial=false,index,national=false,scope,onScope,divisionsLocked=false}:{settings?:ObjectValue;initial?:boolean;divisionsLocked?:boolean;index:SeasonIndex;national?:boolean;scope?:string;onScope?:(v:string)=>void}){
 const numberFields:[string,string,number,number,number][]=[['startScore','Startscore',501,2,1001],['legs','Aantal legs',5,1,21],['roundDays','Dagen tussen speelrondes',7,1,35],['windowDays','Dagen per speelvenster',7,1,35],['boardCount','Aantal beschikbare banen',3,1,16],['capacity','Maximaal aantal deelnemers',24,2,128],['pointsWin','Punten winst',2,0,10],['pointsDraw','Punten gelijkspel',1,0,10],['pointsLoss','Punten verlies',0,0,10],['lineupHours','Opstellingsdeadline in uren',24,0,168],['confirmHours','Uitslagtermijn in uren',48,1,168],['checkInMinutes','Check-in vóór start in minuten',30,0,180],['promotionPlaces','Promotieplaatsen',1,0,10],['relegationPlaces','Degradatieplaatsen',1,0,10],['slotMinutes','Minuten per speelblok',45,15,240],['inhaalWeeks','Inhaalweken',1,0,8],['ladderDistance','Ladder: plaatsen omhoog',3,1,10],['ladderAnswerHours','Ladder: antwoordtermijn uren',48,1,168],['ladderPlayDays','Ladder: speeltermijn dagen',7,1,30]];
 const selectFields:[string,string,[string,string][],string][]=[['scheduleMode','Planning',[['fixed','Vaste speelavond'],['flex','Flexrondes']],'fixed'],['playMode','Spelen',[['local','Op locatie'],['remote','Op afstand'],['hybrid','Hybride: afspraak per ontmoeting']],'local'],['legMode','Wedstrijdlengte',[['bestOf','Best of'],['fixed','Vast aantal legs']],'bestOf'],['ranking','Stand op',[['points','Competitiepunten'],['legs','Gewonnen legs']],'points'],['visibility','Zichtbaarheid',[['members','Verenigingsleden'],['public','Openbaar'],['invite','Op uitnodiging']],'members'],['slotCount','Partijen per teamontmoeting',[['4','Vier singles'],['7','Vier singles, twee koppels en teamgame']],'4'],['withdrawalPolicy','Terugtrekking',[['progress','Volgens voortgang'],['preserve','Gespeelde uitslagen behouden'],['remove','Ontmoetingen vervallen']],'progress']];
 return <div className="season-field-grid">
  {initial&&<><Field label="Seizoensnaam" wide><input name="name" required maxLength={80} placeholder="Clubcompetitie 2027"/></Field><Field label="Competitie"><Select name="scope" options={[["internal","Interne clubcompetitie"],...(index.canCreateNational?[["national","Landelijke competitie"] as [string,string]]:[])]} value={scope} onChange={onScope}/></Field><Field label="Vereniging"><Select name="clubId" required={!national} options={[["",national?'Landelijke organisatie':'Kies een vereniging'],...index.clubs.filter(club=>club.canManage!==false).map(club=>[club.id,club.name] as [string,string])]}/></Field><Field label="Format"><Select name="format" options={Object.entries(formats).filter(([id])=>national?['singles','teams','champions'].includes(id):id!=='champions')} value={national?'teams':'singles'}/></Field></>}
  <Field label="Speelklassen"><input name="divisions" disabled={divisionsLocked} defaultValue={Array.isArray(settings.divisions)?settings.divisions.map(v=>typeof v==='string'?v:txt(obj(v).name)).join(', '):national?'Hoofdklasse':'Divisie 1'} required maxLength={120}/></Field>
  <Field label="Divisieniveaus (zelfde niveau = parallelpoules)"><input name="divisionLevels" placeholder="1, 1, 2" defaultValue={txt(settings.divisionLevels,Array.isArray(settings.divisions)?settings.divisions.map((_,i)=>String(i+1)).join(', '):'1')}/></Field><Field label="Richtgrootte poule"><input type="number" name="divisionSize" min={8} max={12} defaultValue={10}/></Field><Field label="Eerste speeldatum"><input type="date" name="startDate" defaultValue={txt(settings.startDate)} required/></Field><Field label="Aanvang"><input type="time" name="playTime" defaultValue={txt(settings.playTime,'19:30')} required/></Field>
  <StartProcedureFields settings={settings as Partial<import('@/lib/types').Settings>}/>
  {!national&&<SeasonComponentRules settings={settings as import('@/lib/seasons-types').SeasonSettings}/>}
  <Field label="Aantal sets (best of)"><Select name="bestOfSets" options={[["1","1 set"],["3","Best of 3 sets"],["5","Best of 5 sets"]]} value={txt(settings.bestOfSets,'1')}/></Field>
  {selectFields.map(([name,label,options,fallback])=><Field key={name} label={label}><Select name={name} options={options} value={txt(settings[name],fallback)}/></Field>)}
  {numberFields.map(([name,label,fallback,min,max])=><Field key={name} label={label}><input name={name} type="number" min={min} max={max} required defaultValue={num(settings[name],fallback)}/></Field>)}
  <Field label="Speelvrije data" wide><input name="blackouts" placeholder="2027-01-01, 2027-01-08" defaultValue={ids(settings.blackouts).join(', ')}/></Field>
  <Field label="Transferdeadline (met tijdzone)"><input name="transferDeadline" type="text" placeholder="2027-02-01T23:00:00Z" defaultValue={txt(settings.transferDeadline)}/></Field><Field label="Neutrale locatie"><Select name="neutralClubId" options={[["","Thuisvereniging"],...index.clubs.map(club=>[club.id,club.name] as [string,string])]} value={txt(settings.neutralClubId)}/></Field>
  <Field label="Tijdzone"><Select name="timezone" options={[["Europe/Amsterdam","Nederland · Europe/Amsterdam"]]} value={txt(settings.timezone,'Europe/Amsterdam')}/></Field>
  <Field label="Aanvullend reglement" wide><textarea name="notes" maxLength={2000} rows={3} defaultValue={txt(settings.notes)}/></Field>
  <Check name="roundGating" checked={Boolean(settings.roundGating)}>Speelrondes handmatig vrijgeven</Check><Check name="allowMultipleTeams" checked={Boolean(settings.allowMultipleTeams)}>Meerdere teams per vereniging toestaan</Check><Check name="returnLegs" checked={Boolean(settings.returnLegs)}>Ook een thuis- en uitronde</Check><Check name="cameraRequired" checked={Boolean(settings.cameraRequired)}>Camera vereist bij remote partijen</Check>
 </div>;
}
function SeasonWizard({index,command,busy,onClose}:{index:SeasonIndex;command:Command;busy:boolean;onClose:()=>void}){
 const [scope,setScope]=useState(!index.clubs.some(club=>club.canManage)&&index.canCreateNational?'national':'internal'),[preset,setPreset]=useState(!index.clubs.some(club=>club.canManage)&&index.canCreateNational?'national':'club'),[preview,setPreview]=useState<ObjectValue|null>(null);const form=useRef<HTMLFormElement>(null);
 function choose(value:string){setPreset(value);setScope(value==='national'||value==='cup'?'national':'internal');const element=form.current;if(!element)return;const controls:{[key:string]:string}={scheduleMode:value==='flex'?'flex':'fixed',format:value==='national'?'teams':value==='cup'?'champions':'singles',slotCount:'4',playMode:'local'};for(const [key,val] of Object.entries(controls)){const input=element.elements.namedItem(key);if(input instanceof HTMLInputElement||input instanceof HTMLSelectElement)input.value=val;}}
 async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const values=formValues(event.currentTarget);const {name,format,clubId,divisions,...settings}=values;const result=await command({type:'season.create',name,scope,format,clubId:clubId||null,divisions,settings},'Seizoen aangemaakt.');if(result){onClose();navigate(`${base}/${result.id}`);}}
 return <Modal title="Nieuw competitieseizoen" onClose={onClose}><form ref={form} onSubmit={submit}>{index.actorId&&<OrganizerDrafts actorId={index.actorId} kind="season"/>}<div className="season-preset-row">{[['club','Clubavond'],['flex','Flexcompetitie'],...(index.canCreateNational?[["national","Landelijk · vier singles"]]:[]),...(index.canCreateNational?[["cup","Champions Cup"]]:[])].map(([id,label])=><button key={id} type="button" className="season-button season-quiet" aria-pressed={preset===id} onClick={()=>choose(id)}>{label}</button>)}</div><SettingsFields index={index} initial scope={scope} national={scope==='national'} onScope={value=>{setScope(value);const format=form.current?.elements.namedItem('format');if(format instanceof HTMLSelectElement)format.value=value==='national'?'teams':'singles';}}/><div className="season-footer-actions"><Button icon="table" onClick={()=>setPreview(form.current?formValues(form.current):null)}>Bekijk voorbeeldstand</Button><Button primary type="submit" icon="plus" disabled={busy}>Maak seizoen aan</Button></div>{preview&&<div className="season-point-preview" role="status">Bij winst {txt(preview.pointsWin)} punten, gelijkspel {txt(preview.pointsDraw)} punten en verlies {txt(preview.pointsLoss)} punten. {preview.ranking==='legs'?'Gewonnen legs bepalen de stand.':'De officiële, bevestigde uitslagen bepalen de stand.'}</div>}</form></Modal>;
}
function SeasonCard({season,index}:{season:SeasonView;index:SeasonIndex}){const fixtures=rows(season.fixtures),completed=fixtures.filter(f=>finalStates.has(txt(f.status))).length,progress=fixtures.length?Math.round(completed/fixtures.length*100):0,team=season.format==='teams'||season.format==='doubles';return <article className="season-season-card" data-scope={season.scope}><div className="season-card-top"><span className="season-emblem"><Glyph name={season.scope==='national'?'globe':'trophy'} size={23}/></span><Badge status={season.status}/></div><div className="season-card-body"><small className="season-meta">{season.scope==='national'?'Landelijke competitie':index.clubs.find(club=>club.id===season.clubId)?.name??'Vereniging'}</small><h2><a href={`${base}/${season.id}`}>{season.name}</a></h2><div className="season-card-meta"><span><Glyph name="users" size={15}/>{seasonEntries(season).length} {team?'teams':'spelers'}</span><span><Glyph name="target" size={15}/>{formats[season.format]??season.format}</span></div></div><div className="season-progress-line"><span>{completed} van {fixtures.length} {team?'ontmoetingen':'partijen'}</span><span>{progress}%</span></div><div className="season-progress" role="progressbar" aria-label="Voortgang seizoen" aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100}><span style={{width:`${progress}%`}}/></div><a className="season-card-link" href={`${base}/${season.id}`}>Bekijk competitie <Glyph name="arrow"/></a></article>;}
function IndexView({index,onWizard}:{index:SeasonIndex;onWizard:()=>void}){const [scope,setScope]=useState('all'),[archived,setArchived]=useState(false);const visible=index.seasons.filter(season=>(scope==='all'||season.scope===scope)&&(archived?season.status==='archived':season.status!=='archived'));return <><header className="season-hero season-index-hero"><div className="season-hero-copy"><div className="season-overline"><Glyph name="trophy" size={15}/> DartFlow competities</div><h1>Competities</h1><p>Volg het klassement van je vereniging en speel tegen clubs uit heel Nederland.</p></div>{(index.canCreateNational||index.canCreateInternal||index.clubs.some(club=>club.canManage))&&<Button primary icon="plus" onClick={onWizard}>Nieuw seizoen</Button>}</header><div className="season-toolbar"><nav className="season-tabs" aria-label="Type competitie">{[['all','Alle competities'],['internal','Vereniging'],['national','Landelijk']].map(([id,label])=><button key={id} type="button" aria-pressed={scope===id} onClick={()=>setScope(id)}>{label}</button>)}</nav><button className="season-button season-quiet" type="button" aria-pressed={archived} onClick={()=>setArchived(!archived)}><Glyph name="clock"/>{archived?'Toon huidige seizoenen':'Toon archief'}</button></div>{visible.length?<div className="season-season-grid">{visible.map(season=><SeasonCard key={season.id} season={season} index={index}/>)}</div>:<Panel title={archived?'Archief':'Jouw competities'}><Empty title={archived?'Nog geen gearchiveerde seizoenen':'Nog geen competities beschikbaar'}>Een openbaar seizoen of seizoen van jouw vereniging verschijnt hier zodra je toegang hebt.</Empty></Panel>}</>;}
function Stand({season,division,compact=false}:{season:SeasonView;division:string;compact?:boolean}){const list=season.standings.filter(row=>!division||row.divisionId===division);return <Panel title="Stand" aside={season.canManage?<a className="season-button season-quiet" href={`/api/seasons/${season.id}/export?kind=standings`}><Glyph name="download"/>Exporteer stand</a>:null}>{list.length?<><div className="season-scroll" tabIndex={0} role="region" aria-label="Competitiestand, horizontaal scrollbaar"><table className="season-table"><caption>Alleen definitieve uitslagen · {season.settings.ranking==='legs'?'gewonnen legs':'competitiepunten'} · {season.settings.pointsWin}/{season.settings.pointsDraw}/{season.settings.pointsLoss}</caption><thead><tr>{['#',season.format==='teams'?'Team':'Speler','G','W','Gelijk','V','Ptn',...(compact?[]:['Partijen']),'Legs','Vorm'].map(h=><th key={h} scope="col">{h}</th>)}</tr></thead><tbody>{list.map(row=><tr key={row.id}><td className="season-position">{row.position}{row.shared&&<span title="Gedeelde positie"> =</span>}</td><th scope="row" className="season-highlight">{row.name}</th><td>{row.played}</td><td>{row.won}</td><td>{row.drawn}</td><td>{row.lost}</td><td><strong>{row.points}</strong>{row.deduction!==0&&<small title="Puntencorrectie"> ({row.deduction>0?'-':'+'}{Math.abs(row.deduction)})</small>}</td>{!compact&&<td>{row.partiesFor}–{row.partiesAgainst}</td>}<td>{row.legsFor}–{row.legsAgainst}</td><td><span className="season-form-streak" aria-label={row.form.map(v=>v==='W'?'Gewonnen':v==='V'?'Verloren':'Gelijk').join(', ')}>{row.form.map((v,i)=><span key={i} data-result={v}>{v}</span>)}</span></td></tr>)}</tbody></table></div><p className="season-meta">G = gespeeld · W = gewonnen · Gelijk = gelijkgespeeld · V = verloren. Vorm: meest recente uitslag eerst.</p></>:<Empty title="Nog geen definitieve stand">Bevestigde uitslagen verschijnen hier automatisch.</Empty>}</Panel>;}
function FixtureRow({season,fixture,onOpen}:{season:SeasonView;fixture:SeasonFixture;onOpen:()=>void}){const decided=fixture.slots.every(slot=>['confirmed','administrative'].includes(slot.status)),score=fixture.administrative?.score??((season.format==='teams'||season.format==='doubles')?[fixture.slots.filter(slot=>slot.administrative?.winner===0||slot.score&&slot.score[0]>slot.score[1]).length,fixture.slots.filter(slot=>slot.administrative?.winner===1||slot.score&&slot.score[1]>slot.score[0]).length]:fixture.slots[0]?.score);return <div className="season-fixture-row"><div className="season-fixture-when"><Glyph name="calendar"/><div>{dateLabel(fixture.startsAt)}<small>{fixture.boardIds.length?`${fixture.boardIds.length} baan${fixture.boardIds.length>1?'banen':''}`:'Baan nog te bepalen'}</small></div></div><div className="season-fixture-sides"><strong>{entryName(season,fixture.homeId)}</strong><span>{score&&(decided||fixture.status!=='scheduled')?score.join('–'):'–'}</span><strong>{entryName(season,fixture.awayId)}</strong></div><div className="season-fixture-action"><Badge status={fixture.status}/><Button icon="arrow" onClick={onOpen}>{finalStates.has(fixture.status)?'Bekijk uitslag':'Open wedstrijd'}</Button></div></div>;}
function Program({season,user,division,onOpen,results=false}:{season:SeasonView;user:Profile;division:string;onOpen:(id:string)=>void;results?:boolean}){const [mine,setMine]=useState(false),[round,setRound]=useState('');const list=season.fixtures.filter(fixture=>(!division||fixture.divisionId===division)&&(!round||String(fixture.round)===round)&&(!mine||sideOf(season,obj(fixture),user)||fixture.slots.some(slot=>slot.players.includes(user.id)))&&(!results||['provisional','confirmed','administrative','disputed'].includes(fixture.status)));const rounds=[...new Set(list.map(fixture=>fixture.round))].sort((a,b)=>a-b);return <><div className="season-toolbar"><nav className="season-tabs" aria-label="Wedstrijdfilter">{[[false,'Alle wedstrijden'],[true,'Mijn wedstrijden']].map(([value,label])=><button type="button" key={String(value)} aria-pressed={mine===value} onClick={()=>setMine(Boolean(value))}>{label}</button>)}</nav><Field label="Speelronde"><Select name="round" value={round} onChange={setRound} options={[["","Alle rondes"],...season.rounds.map(item=>[String(item.number),`Speelronde ${item.number}`] as [string,string])]}/></Field><a className="season-button season-quiet" href={`/api/seasons/${season.id}/calendar.ics`}><Glyph name="download"/>Agenda-export</a></div>{rounds.length?rounds.map(roundNumber=><Panel key={roundNumber} title={list.filter(f=>f.round===roundNumber).every(f=>f.classification)?`Plaatsingsbeslissing ${roundNumber}`:`Speelronde ${roundNumber}`}  aside={<span className="season-meta">{season.rounds.find(round=>round.number===roundNumber)?.released?'Vrijgegeven':'Nog niet vrijgegeven'}</span>}>{list.filter(fixture=>fixture.round===roundNumber).map(fixture=><FixtureRow key={fixture.id} season={season} fixture={fixture} onOpen={()=>onOpen(fixture.id)}/>)}</Panel>):<Panel title={results?'Uitslagen':'Programma'}><Empty title={results?'Geen uitslagen gevonden':'Geen wedstrijden gevonden'}>Pas het filter aan of wacht op publicatie van het programma.</Empty></Panel>}</>;}
function Statistics({season,division}:{season:SeasonView;division:string}){const eligible=new Set(season.participants.filter(p=>!division||p.divisionId===division).map(p=>p.id));if(season.format==='teams'||season.format==='doubles')for(const team of season.teams.filter(team=>!division||team.divisionId===division))team.playerIds.forEach(id=>eligible.add(id));const stats=season.statistics.filter(player=>!division||eligible.has(player.playerId));return <Panel title="Spelersstatistieken" aside={<Badge status="confirmed" label="Definitief gespeelde partijen"/>}>{stats.length?<div className="season-scroll" tabIndex={0} role="region" aria-label="Seizoensstatistieken, horizontaal scrollbaar"><table className="season-table"><caption>Dezelfde geaccepteerde scorekaart als in het spelersprofiel. Onbekende oude gegevens blijven leeg.</caption><thead><tr>{['Speler','Gespeeld','3-dart AVG','First 9','Beste leg','Hoogste finish','180’s'].map(label=><th key={label} scope="col">{label}</th>)}</tr></thead><tbody>{stats.map(player=><tr key={player.playerId}><th scope="row">{player.name}</th><td>{player.played}</td><td>{decimal(player.average)}</td><td>{decimal(player.firstNine)}</td><td>{player.bestLegDarts??'—'}</td><td>{player.highestFinish||'—'}</td><td>{player.oneEighties}</td></tr>)}</tbody></table></div>:<Empty title="Nog geen gespeelde resultaten">Statistieken verschijnen na definitieve afronding. Administratieve uitslagen leveren geen worpstatistieken op.</Empty>}</Panel>;}
