function CopyDialog({season,command,busy,onClose}:{season:SeasonView;command:Command;busy:boolean;onClose:()=>void}){return <Modal title="Kopieer seizoen" onClose={onClose}><form onSubmit={async e=>{e.preventDefault();const data=new FormData(e.currentTarget),result=await command({type:'season.copy',seasonId:season.id,name:data.get('name'),copyEntries:data.has('copyEntries'),applyPromotions:data.has('applyPromotions')},'Nieuw conceptseizoen aangemaakt.');if(result)navigate(`${base}/${result.id}`);}}><Field label="Naam nieuw seizoen"><input name="name" defaultValue={`${season.name} · nieuw seizoen`} required maxLength={80}/></Field><Check name="copyEntries" checked>Neem deelnemers en divisie-indeling over</Check>{season.promotionPlan&&<Check name="applyPromotions" checked={season.promotionPlan.complete}>Neem definitieve promotie en degradatie over</Check>}<p className="season-field-help">Het nieuwe seizoen krijgt een eigen identiteit. De bestaande uitslagen en gepubliceerde reglementsversie blijven in het archief.</p><div className="season-footer-actions"><Button primary type="submit" icon="plus" disabled={busy}>Maak concept</Button></div></form></Modal>;}
function OverviewPanel({season,user,division,onOpen}:{season:SeasonView;user:Profile;division:string;onOpen:(id:string)=>void}){const fixtures=season.fixtures.filter(f=>!division||f.divisionId===division),upcoming=fixtures.filter(f=>!finalStates.has(f.status)).sort((a,b)=>(a.startsAt??a.windowStart).localeCompare(b.startsAt??b.windowStart)),mine=upcoming.find(f=>sideOf(season,obj(f),user)||f.slots.some(slot=>slot.players.includes(user.id))),team=season.format==='teams'||season.format==='doubles';return <div className="season-detail-grid"><div><Panel title={team?'Jouw volgende ontmoeting':'Jouw volgende partij'} className={mine?'season-next':''} aside={mine?<Badge status={mine.status}/>:null}>{mine?<><div className="season-next-main"><span className="season-emblem"><Glyph name="target" size={25}/></span><div><small className="season-meta">Speelronde {mine.round}</small><h3>{entryName(season,sideOf(season,obj(mine),user)==='home'?mine.awayId:mine.homeId)}</h3><p>{dateLabel(mine.startsAt)}{mine.boardIds.length?' · Baan toegewezen':''}</p></div></div><Button primary icon="arrow" onClick={()=>onOpen(mine.id)}>Open wedstrijd</Button></>:<Empty title="Geen partij gepland">Je vindt alle speelrondes in Programma.</Empty>}</Panel><Stand season={season} division={division}/></div><aside><Panel title="Binnenkort">{upcoming.length?<div className="season-mini-list">{upcoming.slice(0,3).map(f=><button type="button" key={f.id} onClick={()=>onOpen(f.id)}><span><Glyph name="calendar"/></span><div><strong>{entryName(season,f.homeId)} – {entryName(season,f.awayId)}</strong><small>{dateLabel(f.startsAt)}</small></div><Glyph name="arrow"/></button>)}</div>:<Empty title="Geen wedstrijden gepland"/>}</Panel><Panel title="Seizoen"><Definitions values={[["Speelvorm",formats[season.format]],["Planning",season.settings.scheduleMode==='flex'?'Flexrondes':'Vaste speelavond'],["Wedstrijdvorm",season.settings.playMode==='hybrid'?'Hybride: per ontmoeting vastleggen':season.settings.playMode==='remote'?'Op afstand':'Op locatie'],["Reglement",`Versie ${season.rulesVersion}`],["Voortgang",`${fixtures.filter(f=>finalStates.has(f.status)).length} van ${fixtures.length} ${team?'ontmoetingen':'partijen'}`]]}/></Panel></aside></div>;}
async function api<T>(path:string,data?:unknown,signal?:AbortSignal):Promise<T>{const response=await fetch(path,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?undefined:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal});const result=await response.json();if(!response.ok)throw new Error(typeof result.error==='string'?result.error:'Dit is niet gelukt. Haal de actuele competitie op en probeer opnieuw.');return result;}
