 const refresh=useCallback(async(signal?:AbortSignal)=>{const current=++version.current;try{const [catalog,detail]=await Promise.all([id&&catalogCache.current?Promise.resolve(catalogCache.current):api<SeasonIndex>('/api/seasons',undefined,signal),id?api<{season:SeasonView}>(`/api/seasons/${encodeURIComponent(id)}`,undefined,signal):Promise.resolve(null)]);if(!mounted.current||current!==version.current)return;catalogCache.current={...catalog,actorId:user.id};setIndex(catalogCache.current);setSeason(detail?.season??null);setError('');}catch(error){if(signal?.aborted||!mounted.current||current!==version.current)return;setError(error instanceof Error?error.message:'De competitie kan niet worden geladen.');}finally{if(mounted.current&&current===version.current)setLoading(false);}},[id,user.id]);
