 useEffect(()=>{if(!id)return;const timer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy&&!dialog)void refresh();},15000);return()=>clearInterval(timer);},[id,refresh,busy,dialog]);
 useEffect(()=>{const back=()=>{setTab(initialTab());const fixture=new URLSearchParams(location.search).get('fixture');setFixtureId(fixture??'');setDialog(fixture?'fixture':null);};window.addEventListener('popstate',back);return()=>window.removeEventListener('popstate',back);},[]);
 function chooseTab(value:Tab){setTab(value);setMessage('');const url=new URL(location.href);url.searchParams.set('tab',value);history.pushState(null,'',url.pathname+url.search);}
