 function closeDialog(){setDialog(null);const url=new URL(location.href);if(url.searchParams.has('fixture')){url.searchParams.delete('fixture');history.replaceState(null,'',url.pathname+url.search);}}
 const command:Command=async(action,success='Wijziging opgeslagen.')=>{if(busy)return null;setBusy(true);setError('');setMessage('');const fingerprint=JSON.stringify({action,expectedRevision:season?.revision}),requestId=attempts.current.get(fingerprint)??crypto.randomUUID();attempts.current.set(fingerprint,requestId);try{const result=await api<CommandResult>('/api/seasons',{requestId,...(season?{expectedRevision:season.revision}:{}),action});attempts.current.delete(fingerprint);if(!mounted.current)return null;if(result.season){setSeason(result.season);setIndex(current=>current?{...current,seasons:[...current.seasons.filter(s=>s.id!==result.season.id),result.season]}:current);}setMessage(success);return result;}catch(error){if(mounted.current)setError(error instanceof Error?error.message:'Opslaan is niet gelukt.');return null;}finally{if(mounted.current)setBusy(false);}};
